def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    own = [h[0] for h in history]

    opp_d = 0
    own_d = 0
    for x in opp:
        if x == 'D':
            opp_d += 1
    for x in own:
        if x == 'D':
            own_d += 1
    opp_c = n - opp_d

    last_opp = opp[-1]
    last_own = own[-1]

    def streak(seq, ch):
        s = 0
        for x in reversed(seq):
            if x == ch:
                s += 1
            else:
                break
        return s

    opp_d_streak = streak(opp, 'D')
    my_d_streak = streak(own, 'D')

    if n < 4:
        return 'C'

    w = 12
    if n < w:
        w = n
    recent_opp_d = 0
    for i in range(n - w, n):
        if opp[i] == 'D':
            recent_opp_d += 1

    if n < 15:
        if opp_d >= 3 and recent_opp_d >= 3:
            return 'D'
        if last_opp == 'D':
            if last_own == 'C' or my_d_streak == 0:
                return 'D'
            if opp_d_streak >= 3:
                return 'D'
            if rng.random() < 0.6:
                return 'C'
            return 'D'
        return 'C'

    if last_opp == 'D':
        if opp_d_streak >= 3:
            if rng.random() < 0.08 and opp_d_streak < 6:
                return 'C'
            return 'D'
        if opp_d_streak == 2:
            if last_own == 'D' and rng.random() < 0.3:
                return 'C'
            return 'D'
        if last_own == 'C':
            return 'D'
        if rng.random() < 0.35:
            return 'C'
        return 'D'

    opp_rate = opp_d / float(n)
    recent_rate = recent_opp_d / float(w)

    remaining = 100 - n
    if remaining <= 3:
        if remaining <= 1:
            return 'D'
        if opp_rate < 0.25 and recent_rate < 0.25:
            return 'D'
        if opp_rate > 0.6:
            return 'D'
        return 'C'

    if recent_opp_d == 0 and opp_d_streak == 0:
        if opp_rate < 0.2:
            if remaining <= 8:
                if rng.random() < 0.5:
                    return 'D'
                return 'C'
            if rng.random() < 0.12:
                return 'D'
            return 'C'
        if opp_rate < 0.45:
            if rng.random() < 0.06:
                return 'D'
            return 'C'
        if rng.random() < 0.03:
            return 'C'
        return 'D'

    if recent_rate > 0.6:
        return 'D'
    if recent_rate > 0.35:
        if rng.random() < 0.25:
            return 'C'
        return 'D'

    if opp_rate > 0.55:
        if rng.random() < 0.12:
            return 'C'
        return 'D'

    if last_own == 'D' and opp_d_streak == 0:
        return 'C'

    if rng.random() < 0.1:
        return 'D'
    return 'C'
